const portadaUrl = $('9 PDF.co (pdfEditAdd)').first().json.url;
const sortItems = $input.all().map(item => item.json || {});

const docsUrls = sortItems
  .map(item => item.url)
  .filter(Boolean);

const listaFinal = [portadaUrl, ...docsUrls].filter(Boolean);
const camposVacios = sortItems[0]?.camposVacios || [];
const source = sortItems.some(item => item.source === 'drive_fallback')
  ? 'drive_fallback'
  : 'airtable';

return [{
  json: {
    urls_unificadas: listaFinal.join(','),
    total_documentos: listaFinal.length,
    nombre_archivo: `Dossier_${ $('Sorted Fields').first().json.numero_expediente || 'Sin-Nombre' }.pdf`,
    camposVacios,
    source,
    used_drive_fallback: source === 'drive_fallback',
    decrypted_count: sortItems.filter(item => item.decrypted).length,
    decrypt_failed_count: sortItems.filter(item => item.decrypt_failed).length
  }
}];

const allInputs = $input.all();
let deal = {};
let dealFields = [];
let personFields = [];

for (const item of allInputs) {
  const data = item.json;
  if (data.title && data.id && !Array.isArray(data.data)) {
    deal = data;
  } else if (data.data && Array.isArray(data.data)) {
    if (data.data.some(f => f.key === 'title' || f.name === 'Title')) {
      dealFields = data.data;
    } else {
      personFields = data.data;
    }
  }
}

if (!deal.id && deal.data?.id) deal = deal.data;

const dealFieldDict = {};
dealFields.forEach(f => { dealFieldDict[f.key] = f; });
const personFieldDict = {};
personFields.forEach(f => { personFieldDict[f.key] = f; });

function resolveValue(key, value) {
  const field = dealFieldDict[key] || personFieldDict[key];
  if (field && field.options && value) {
    const option = field.options.find(o => String(o.id) === String(value));
    return option ? option.label : value;
  }
  return value;
}

// Función auxiliar para formateo de moneda Euro
const fmtEuro = (val) => (Number(val) || 0).toLocaleString('es-ES') + ' €';

const cf = deal; 
const output = {
