const d = $('Diccionary').first().json;


// Procesar notas en líneas de ~110 caracteres
const notasRaw = d.notas_operacion
  ? String(d.notas_operacion)
      .replace(/\r?\n/g, ' ')
      .replace(/\t/g, ' ')
      .replace(/"/g, "'")
      .replace(/\\/g, '')
      .trim()
      .substring(0, 900)
  : '';
function splitLines(text, maxLen) {
  const words = text.split(' ');
  const lines = [];
  let current = '';
  for (const word of words) {
    if ((current + ' ' + word).trim().length <= maxLen) {
      current = (current + ' ' + word).trim();
    } else {
      if (current) lines.push(current);
      current = word;
    }
  }
  if (current) lines.push(current);
  return lines;
}
const nl = splitLines(notasRaw, 110);
return [{
  json: {
    deal_id:           d.deal_id,
    numero_expediente: d.numero_expediente,
    person_name_t1:    d.person_name_t1,
    user_email:        d.user_email,
    // Titular 1
    dni_t1:            d.dni_t1,
    edad_t1:           String(d.edad_t1 ?? ''),
    email_t1:          d.email_t1,
    phone_t1:          d.phone_t1,
    estado_civil_t1:   d.estado_civil_t1,
    tipo_contrato_t1:  d.tipo_contrato_t1,
