    edad_t2:           String(d.edad_t2 ?? ''),
    email_t2:          d.email_t2,
    phone_t2:          d.phone_t2,
    estado_civil_t2:   d.estado_civil_t2,
    tipo_contrato_t2:  d.tipo_contrato_t2,
    antiguedad_t2:     String(d.antiguedad_t2 ?? ''),
    total_income_t2:   d.nombre_t2 ? d.total_income_t2_fmt : '',
    cuota_prestamos_t2: d.nombre_t2 ? d.prestamos_t2_fmt : '',
    // Operación
    direccion:         d.direccion,
    provincia:         d.provincia,
    tipo_compra:       d.tipo_compra,
    mortgage_type:     d.mortgage_type,
    property_type:     d.property_type,
    term:              d.term,
    precio_vivienda:   d.precio_vivienda_fmt,
    importe_hipoteca:  d.importe_hipoteca_fmt,
