    notas_1: nl[0] || '',
    notas_2: nl[1] || '',
    notas_3: nl[2] || '',
    notas_4: nl[3] || '',
    notas_5: nl[4] || '',
    notas_6: nl[5] || '',
    // Bancos y Ofertas
    banco_1: d.banco_1, importe_1: d.importe_1, link_b1: d.link_b1,
    banco_2: d.banco_2, importe_2: d.importe_2, link_b2: d.link_b2,
    banco_3: d.banco_3, importe_3: d.importe_3, link_b3: d.link_b3,
    banco_4: d.banco_4, importe_4: d.importe_4, link_b4: d.link_b4,
    banco_5: d.banco_5, importe_5: d.importe_5, link_b5: d.link_b5
  }
