const record = $input.first()?.json || {};

const camposT1 = [
  'Adjuntar DNI',
  'Vida laboral',
  '3 últimas nóminas',
  'Contrato de trabajo',
  'IRPF o Certificado de Retenciones',
  'Movimientos de cuenta',
  '3 últimos recibos préstamo pendiente (si los hay)',
  'Escritura de hipoteca (si la hay)',
  'Escritura de compraventa (si la hay)',
  'Otros (si los hay)',
  'Portada de Dossier',
  'Portada de Dossier B'
];

const camposT2 = [
  'Adjuntar DNI - Segundo Titular',
  'Vida Laboral - Segundo Titular',
  '3 últimas nóminas - Segundo Titular',
  'Contrato de trabajo - Segundo Titular',
  'IRPF o Certificado de Retenciones - Segundo Titular',
  'Movimientos de cuenta - Segundo Titular'
];

const sorted = (() => {
  try {
    return $('Sorted Fields').first().json || {};
  } catch (e) {
    return {};
  }
})();

function norm(value) {
  return String(value ?? '')
    .trim()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toUpperCase();
}

const nombreT2 =
  record.nombre_t2 ||
  record['Titular 2 - Nombre y apellidos'] ||
  sorted.nombre_t2 ||
  '';

const haySegundoTitular = norm(
  record['¿Hay segundo titular?'] ??
  record['Hay segundo titular'] ??
  record['Segundo titular'] ??
  sorted['¿Hay segundo titular?'] ??
  sorted.hay_segundo_titular ??
  ''
);

const nombreT2Norm = norm(nombreT2);
const tieneDocsT2 = camposT2.some(campo => Array.isArray(record[campo]) && record[campo].length > 0);

const tieneST =
  ['SI', 'TRUE', 'YES', '1'].includes(haySegundoTitular) ||
  tieneDocsT2 ||
  (
    !['NO', 'FALSE', '0'].includes(haySegundoTitular) &&
    Boolean(nombreT2Norm) &&
    !['NO TIENE', 'N/A', 'NA', 'NULL', 'UNDEFINED', '-'].includes(nombreT2Norm)
  );

const campos = tieneST ? [...camposT1, ...camposT2] : camposT1;

const items = [];
const camposVacios = [];
const source = record.__source || 'airtable';

for (const campo of campos) {
  if (Array.isArray(record[campo]) && record[campo].length > 0) {
    for (const archivo of record[campo]) {
      items.push({
        json: {
          url: archivo.url,
          size: archivo.size,
          filename: archivo.filename || archivo.name || '',
          field: campo,
          code: archivo.code || '',
          source: archivo.source || source,
          decrypted: Boolean(archivo.decrypted),
          decrypt_failed: Boolean(archivo.decrypt_failed),
          camposVacios: []
        }
      });
    }
  } else {
    const esOpcional =
      campo.includes('si los hay') ||
      campo.includes('si la hay') ||
      campo === 'Portada de Dossier' ||
      campo === 'Portada de Dossier B';

    // No bloquea el flujo. Solo alimenta el aviso de Slack/Sheets.
    if (!esOpcional) {
      camposVacios.push(campo);
    }
  }
}

// Todos los documentos son opcionales: si no hay ninguno, seguimos con la portada.
if (items.length === 0) {
  items.push({
    json: {
      url: null,
      size: null,
      filename: '',
      field: '',
      code: '',
      source,
      decrypted: false,
      decrypt_failed: false,
      placeholder: true,
      camposVacios
    }
  });
}

for (const item of items) {
  item.json.camposVacios = camposVacios;
}

return items;

