    'not encrypted',
    'not password protected',
    'not protected',
    'not secured',
    'no password',
    'no security',
    'does not have password',
    'password is not required',
    'not require password'
  ].some(fragment => text.includes(fragment));
}

const resultByOriginalIndex = new Map();

for (let i = 0; i < requests.length; i++) {
  const request = requests[i] || {};
  const response = responses[i] || {};
  const ok = response.error === false && Boolean(response.url);
  const errorMessage = ok ? null : getErrorMessage(response);
  const notEncrypted = !ok && looksLikeNotEncrypted(errorMessage);

  resultByOriginalIndex.set(Number(request.originalIndex), {
    ok,
    url: ok ? response.url : null,
    errorMessage,
    notEncrypted,
    holder: request.holder,
    passwordTried: request.password,
  });
}

const output = originals.map((original, index) => {
  const result = resultByOriginalIndex.get(index);
  if (!result) {
    return { json: { ...original, has_decrypt_failures: false } };
  }

  if (result.ok) {
    return {
      json: {
        ...original,
        url: result.url,
        original_url: original.url,
        decrypted: true,
        decrypt_failed: false,
        decrypt_error: null,
        excluded_from_merge: false,
        has_decrypt_failures: false,
      }
    };
  }

  // If PDF.co says the file is not protected, keep it in the merge.
  if (result.notEncrypted) {
    return {
      json: {
        ...original,
        decrypted: false,
        decrypt_skipped_not_encrypted: true,
        decrypt_failed: false,
        decrypt_error: result.errorMessage,
        excluded_from_merge: false,
        has_decrypt_failures: false,
      }
    };
  }

  // Password/security removal failed: exclude it from merge and notify.
  return {
    json: {
      ...original,
      url: null,
      original_url: original.url,
      decrypted: false,
      decrypt_failed: true,
      decrypt_error: result.errorMessage,
      decrypt_holder: result.holder,
      excluded_from_merge: true,
      has_decrypt_failures: true,
    }
  };
});

const hasFailures = output.some(item => item.json.decrypt_failed && item.json.excluded_from_merge);
return output.map(item => ({
  json: {
    ...item.json,
    has_decrypt_failures: hasFailures,
  }
}));

